/*
 * ============================================================================
 * SHADER: Metamorphosis Volume
 * AUTHOR: dathor
 *
 *  ADDITIONAL CREDITS:   
 * -Based in the fantatic Volumetric Perlin to exact SDF by FabriceNeyret2
 *     https://www.shadertoy.com/view/NXGSRK
 * 
 *
 * 
 * ----------------------------------------------------------------------------
 * DESCRIPTION:
 * A volumetric shape that slowly morphs between a turbulent Perlin cloud and
 * a lotus flower, floating on reflective water at sunset. Both shapes are
 * baked into a 128^3 distance-field volume, so rays can sphere-march up to
 * the surface and then step through the shape for soft, translucent shading.
 *
 * A keyframed camera orbits, skims the water, swoops over the bloom and
 * pulls back in a 40 second loop. The morph is timed to the shots.
 * The water has swells, ripples and rings spreading from the flower, and it
 * reflects both the shape and the sky.
 *
 * A post-process pass adds depth of field, bloom, atmospheric haze and sun
 * god rays, plus a film grade and letterbox bars.
 * ----------------------------------------------------------------------------
 * DEVELOPER NOTES:

      Based on the fantatic Volumetric Perlin to exact SDF by FabriceNeyret2
      https://www.shadertoy.com/view/NXGSRK

      The rest is kind of a mashup of prior work.  


*/

const float SHOT_LEN = 40.0;
const float FADE = 1.5;

const float EXPOSURE = 0.9;

const float BLOOM_RADIUS = .02;
const float BLOOM_GAIN = 1.5;
// const vec3  BLOOM_TINT   = vec3(1.0, 0.82, 0.95);
const vec3 BLOOM_TINT = vec3(1.0, 0.72, 0.45);

const float MIST_GAIN = 0.5;
const float MIST_VEIL = 0.30;
const vec3 MIST_TINT = vec3(0.55, 0.75, 1.0);
const vec3 VEIL_COL = vec3(0.10, 0.18, 0.30);

const float RAYS_GAIN = 1.1;
const float RAYS_DECAY = 0.965;
const float RAYS_DENSITY = 0.95;
const vec3 RAYS_TINT = vec3(1.0, 0.70, 0.42);
const float SUN_CORE = 0.012;
const float SUN_HALO = 3.0;

float luma(vec3 color) { return dot(color, vec3(0.299, 0.587, 0.114)); }

float hash12(vec2 p)
{
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float vnoise2(vec2 p)
{
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash12(i);
    float b = hash12(i + vec2(1.0, 0.0));
    float c = hash12(i + vec2(0.0, 1.0));
    float d = hash12(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm2(vec2 p)
{
    float s = 0.0, a = 0.5;
    for (int i = 0; i < 4; i++) {
        s += a * vnoise2(p);
        p = p * 2.02 + vec2(3.1, 1.7);
        a *= 0.5;
    }
    return s;
}

float shotFade(float T)
{
    float lt = mod(T, SHOT_LEN);
    float fin = (T < FADE) ? 1.0 : smoothstep(0.0, FADE, lt);
    float fout = smoothstep(0.0, FADE, SHOT_LEN - lt);
    return fin * fout;
}

vec3 karisTap(vec2 uv, vec2 ts)
{
    vec3 c0 = texture(iChannel0, uv).rgb;
    vec3 c1 = texture(iChannel0, uv + vec2(-0.75, -0.75) * ts).rgb;
    vec3 c2 = texture(iChannel0, uv + vec2(0.75, -0.75) * ts).rgb;
    vec3 c3 = texture(iChannel0, uv + vec2(-0.75, 0.75) * ts).rgb;
    vec3 c4 = texture(iChannel0, uv + vec2(0.75, 0.75) * ts).rgb;
    float w0 = 2.0 / (1.0 + luma(c0));
    float w1 = 1.0 / (1.0 + luma(c1));
    float w2 = 1.0 / (1.0 + luma(c2));
    float w3 = 1.0 / (1.0 + luma(c3));
    float w4 = 1.0 / (1.0 + luma(c4));
    return (c0 * w0 + c1 * w1 + c2 * w2 + c3 * w3 + c4 * w4) / (w0 + w1 + w2 + w3 + w4);
}

float cocOf(float depth)
{
    float c = smoothstep(20.0, 70.0, abs(depth - 25.0)) * 0.6;
    c *= 1.0 - smoothstep(85.0, 105.0, depth);
    return max(c, smoothstep(12.0, 0.0, depth));
}

vec3 farBloom(vec2 uv, float dither, float bar, float aspect)
{
    const int N = 24;
    const float GOLDEN = 2.39996323;
    vec3 acc = vec3(0.0);
    for (int i = 0; i < N; i++) {
        float r = sqrt((float(i) + 0.5) / float(N)) * BLOOM_RADIUS;
        float th = float(i) * GOLDEN + dither * 6.28318;
        vec2 off = vec2(cos(th), sin(th)) * r;
        off.x /= aspect;
        vec2 q = vec2(clamp(uv.x + off.x, 0.0, 1.0), clamp(uv.y + off.y, bar, 1.0 - bar));
        vec4 s = texture(iChannel0, q);
        float far = smoothstep(30.0, 60.0, s.a) * (1.0 - smoothstep(105.0, 115.0, s.a));
        float L = luma(s.rgb);
        float hot = max(L - 0.25, 0.0);
        acc += s.rgb * (hot * far / (1.0 + L));
    }
    return acc / float(N) * BLOOM_GAIN * BLOOM_TINT;
}

vec3 sampleAtmosphere(vec2 uv, float dither, float aspect, float depth)
{
    float isSky = smoothstep(90.0, 110.0, depth);
    float surf = 1.0 - isSky;

    vec2 q = vec2(uv.x * aspect, uv.y) * 2.0;
    float n = fbm2(q + vec2(iTime * 0.012, -iTime * 0.008));
    float n2 = fbm2(q * 2.2 + vec2(-iTime * 0.02, iTime * 0.01) + 5.2);
    float wisps = smoothstep(0.35, 0.75, n * 0.65 + n2 * 0.35);

    float farFog = smoothstep(30.0, 52.0, depth) * surf;
    vec3 hazeCol = VEIL_COL * MIST_VEIL * farFog * (0.4 + 0.6 * wisps);

    vec3 halo = vec3(0.0);
    if (isSky > 0.01) {
        const int TAPS = 16;
        const float GOLDEN_ANGLE = 2.39996323;
        const float maxRad = 0.07;
        vec3 acc = vec3(0.0);
        float wsum = 0.0;
        for (int j = 0; j < TAPS; j++) {
            float r = sqrt((float(j) + 0.5) / float(TAPS)) * maxRad;
            float a = float(j) * GOLDEN_ANGLE + dither * 6.28318;
            vec2 off = vec2(cos(a), sin(a)) * r;
            off.x /= aspect;
            vec4 s = texture(iChannel0, clamp(uv + off, 0.0, 1.0));
            float sSurf = 1.0 - smoothstep(90.0, 110.0, s.a);
            float wg = 1.0 - 0.7 * (r / maxRad);
            acc += s.rgb * sSurf * wg / (1.0 + luma(s.rgb));
            wsum += wg;
        }
        halo = (acc / wsum) * MIST_GAIN * MIST_TINT * (0.5 + 0.8 * wisps);
    }

    return hazeCol + halo * isSky;
}

vec3 godRays(vec2 uv, vec2 sunUV, float facing, float dither, float aspect)
{
    if (facing <= 0.0)
        return vec3(0.0);

    const int N = 48;
    vec2 delta = (sunUV - uv) * RAYS_DENSITY / float(N);
    vec2 pos = uv + delta * dither;
    float illum = 1.0;
    float sum = 0.0;

    for (int i = 0; i < N; i++) {

        vec2 dv = (pos - sunUV) * vec2(aspect, 1.0);
        float d2 = dot(dv, dv);
        float glow = exp(-d2 / SUN_CORE) + 0.15 * exp(-sqrt(d2) * SUN_HALO);

        float open = 1.0;
        if (pos.x >= 0.0 && pos.x <= 1.0 && pos.y >= 0.0 && pos.y <= 1.0)
            open = smoothstep(90.0, 110.0, texture(iChannel0, pos).a);

        sum += glow * open * illum;
        illum *= RAYS_DECAY;
        pos += delta;
    }

    float s = sum / float(N);
    s = pow(s, 0.8);
    return RAYS_TINT * s * RAYS_GAIN * facing;
}

void mainImage(out vec4 fragColor, vec2 fragCoord)
{
    vec2 texelSize = 1.0 / iResolution.xy;
    vec2 uv = fragCoord * texelSize;

    float targetAspect = 2.35;
    float screenAspect = iResolution.x / iResolution.y;
    float barHeight = max(0.0, (1.0 - (screenAspect / targetAspect)) / 2.0);

    if (uv.y < barHeight || uv.y > 1.0 - barHeight) {
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    vec2 vUV = uv - 0.5;
    float distSq = dot(vUV, vUV);
    vec2 caOffset = vUV * 0.003 * distSq;

    vec3 sharpColor;
    sharpColor.r = karisTap(clamp(uv - caOffset, 0.0, 1.0), texelSize).r;
    sharpColor.g = karisTap(clamp(uv, 0.0, 1.0), texelSize).g;
    sharpColor.b = karisTap(clamp(uv + caOffset, 0.0, 1.0), texelSize).b;

    float pixelDepth = texture(iChannel0, uv).a;
    float coc = cocOf(pixelDepth);

    vec3 sceneCol = sharpColor;
    float dither = fract(sin(dot(fragCoord, vec2(12.9898, 78.233))) * 43758.5453);

    if (coc > 0.01) {
        const int TAPS = 16;
        const float GOLDEN_ANGLE = 2.39996323;
        float radius = coc * 0.0055;
        float randomAngle = dither * 6.28318;

        vec3 acc = vec3(0.0);
        float wSum = 0.0;
        for (int i = 0; i < TAPS; i++) {
            float r = sqrt(float(i) + 0.5) / sqrt(float(TAPS));
            float theta = float(i) * GOLDEN_ANGLE + randomAngle;
            vec2 offset = vec2(cos(theta), sin(theta)) * r * radius;
            offset.x /= screenAspect;

            vec4 tap = texture(iChannel0, clamp(uv + offset, 0.0, 1.0));

            float w = 1.0;
            if (tap.a < pixelDepth)
                w = clamp(cocOf(tap.a) / max(coc, 1e-3), 0.0, 1.0);
            w *= 1.0 / (1.0 + luma(tap.rgb));

            acc += tap.rgb * w;
            wSum += w;
        }
        vec3 blurredColor = (wSum > 0.001) ? acc / wSum : sharpColor;
        sceneCol = mix(sharpColor, blurredColor, smoothstep(0.01, 0.1, coc));
    }

    sceneCol += farBloom(uv, dither, barHeight, screenAspect);

    sceneCol += sampleAtmosphere(uv, dither, screenAspect, pixelDepth);

    vec4 sunInfo = texelFetch(iChannel0, ivec2(0, 0), 0);
    sceneCol += godRays(uv, sunInfo.xy, sunInfo.z, dither, screenAspect);

    vec3 finalColor = sceneCol * EXPOSURE;
    finalColor = finalColor / (1.0 + finalColor);
    finalColor = pow(max(finalColor, 0.0), vec3(1.0 / 2.2));

    float lum = luma(finalColor);
    // vec3 shadowTint = vec3(0.92, 0.96, 1.05);
    vec3 shadowTint = vec3(0.85, 0.97, 1.10);
    // vec3 highlightTint = vec3(1.05, 1.01, 0.95);
    vec3 highlightTint = vec3(1.10, 1.00, 0.88);
    finalColor *= mix(shadowTint, highlightTint, smoothstep(0.1, 0.8, lum));

    // finalColor = mix(vec3(lum), finalColor, 1.05);
    finalColor = mix(vec3(lum), finalColor, 1.15);
    finalColor = mix(finalColor, smoothstep(0.0, 1.0, finalColor), 0.5);

    float vignetteRadial = smoothstep(1.4, 0.35, length(vUV));
    finalColor *= mix(0.72, 1.0, vignetteRadial);

    finalColor += (dither - 0.5) * (1.5 / 255.0);
    finalColor *= shotFade(iTime);



    fragColor = vec4(clamp(finalColor, 0.0, 1.0), 1.0);
}

// ============================================================
//  Adapted from Volumetric Perlin to exact SDF by FabriceNeyret2
//  https://www.shadertoy.com/view/NXGSRK
// ============================================================

const float EPS = .1;
const float VOXEL = 2. / 128.;
const int OCTAVES = 6;
const float LOTUS_NOISE = .15;
const float LOTUS_BASE = -.5;
const vec3 HASH_SEED = vec3(467., 581., 389.);

const int UPDATE_EVERY = 1;

const float SECONDS_PER_KEY = 5.;
const int KEY_COUNT = 8;
const float DEBUG_MORPH = -1.;

float morphAmount(float t)
{
    float p = fract(t / (float(KEY_COUNT) * SECONDS_PER_KEY));
    return smoothstep(.20, .40, p) - smoothstep(.75, .95, p);
}
float currentMorph(float t) { return DEBUG_MORPH >= 0. ? DEBUG_MORPH : morphAmount(t); }

vec3 gradientAt(vec3 cell)
{
    mat3 seeds = mat3(HASH_SEED, 73. - HASH_SEED, HASH_SEED.zxy);
    return 2. * fract(sin(cell * seeds) * 3758.54) - 1.;
}

float cornerValue(vec3 x, vec3 cell, vec3 offset)
{
    vec3 corner = cell + offset;
    return dot(gradientAt(corner), x - corner);
}

float perlinAbs(vec3 x)
{
    vec3 cell = floor(x);
    vec3 w = smoothstep(0., 1., fract(x));

    float n000 = cornerValue(x, cell, vec3(0, 0, 0));
    float n100 = cornerValue(x, cell, vec3(1, 0, 0));
    float n010 = cornerValue(x, cell, vec3(0, 1, 0));
    float n110 = cornerValue(x, cell, vec3(1, 1, 0));
    float n001 = cornerValue(x, cell, vec3(0, 0, 1));
    float n101 = cornerValue(x, cell, vec3(1, 0, 1));
    float n011 = cornerValue(x, cell, vec3(0, 1, 1));
    float n111 = cornerValue(x, cell, vec3(1, 1, 1));

    float nx00 = mix(n000, n100, w.x);
    float nx10 = mix(n010, n110, w.x);
    float nx01 = mix(n001, n101, w.x);
    float nx11 = mix(n011, n111, w.x);

    float nxy0 = mix(nx00, nx10, w.y);
    float nxy1 = mix(nx01, nx11, w.y);

    return 2. * abs(mix(nxy0, nxy1, w.z));
}

float turbulence(vec3 x)
{
    float sum = 0.;
    float scale = 1.;
    for (int i = 0; i < OCTAVES; i++) {
        sum += perlinAbs(x) / scale;
        x *= 2.;
        scale *= 2.;
    }
    return sum;
}

float hash11(float n) { return fract(sin(n * 12.9898) * 43758.5453); }

// IQ's approximate ellipsoid distance formula
float ellipsoid(vec3 p, vec3 radii)
{
    float k0 = length(p / radii);
    float k1 = length(p / (radii * radii));
    return k0 * (k0 - 1.) / max(k1, 1e-4);
}

float petalRing(vec3 q, float count, float rotation, float baseRadius, float baseHeight,
    float tilt, float petalLength, float petalWidth, float thickness,
    float bend, float cup, float seed)
{
    float radius = length(q.xz);
    float angle = atan(q.z, q.x) - rotation;
    float sector = 6.2831853 / count;
    float petalIndex = round(angle / sector);
    float localAngle = angle - petalIndex * sector;

    float d = 1e9;

    for (int j = -1; j <= 1; j++) {
        float a = localAngle + float(j) * sector;
        float petalId = mod(petalIndex - float(j), count);
        float h = hash11(petalId + seed * 31.);

        float petalTilt = tilt + .12 * (h - .5);
        float len = petalLength * (.9 + .2 * h);

        vec3 p = vec3(radius * cos(a) - baseRadius,
            q.y - baseHeight,
            radius * sin(a));

        float c = cos(petalTilt), s = sin(petalTilt);
        float u = p.x * c + p.y * s;
        float v = -p.x * s + p.y * c;
        v -= bend * u * u + cup * p.z * p.z;

        d = min(d, ellipsoid(vec3(u - .5 * len, v, p.z), vec3(.5 * len, thickness, petalWidth)));
    }
    return d;
}
float lotusShape(vec3 q)
{
    float b = LOTUS_BASE;
    float d = 1e9;
    // Did try procedual generation.But did not manage
    // to get the lotus shape i wanted.
    d = min(d, petalRing(q, 9., 0., .10, b, .45, .85, .17, .075, .25, 2.0, 1.)); // outer, spreading
    d = min(d, petalRing(q, 9., .349, .10, b + .02, .75, .85, .16, .075, .30, 2.5, 2.));
    d = min(d, petalRing(q, 8., 0., .11, b + .04, 1.00, .80, .15, .07, .30, 2.5, 3.));
    d = min(d, petalRing(q, 7., .449, .12, b + .06, 1.20, .65, .13, .07, .30, 3.0, 4.));
    d = min(d, petalRing(q, 6., 0., .14, b + .08, 1.38, .48, .10, .065, .20, 3.0, 5.)); // inner, upright

    vec3 p = q - vec3(0., b + .28, 0.);
    vec2 w = vec2(length(p.xz) - .10, abs(p.y) - .03);
    float pod = min(max(w.x, w.y), 0.) + length(max(w, 0.)) - .03;
    d = min(d, pod);

    d = min(d, length(q - vec3(0., b + .04, 0.)) - .12);

    return d;
}

float targetField(vec3 voxel, float m)
{
    vec3 q = voxel / 64. - 1.;
    float n = turbulence(q) / 2. - .274;

    float sphere = 0., lotus = 0.;
    if (m < 1.)
        sphere = length(q) - .6 + 2. * n - .1;
    if (m > 0.)
        lotus = lotusShape(q) + LOTUS_NOISE * n;
    return mix(sphere, lotus, m);
}

void mainVolume(out vec4 O, vec3 V)
{
    float m = currentMorph(iTime);

    bool changing = abs(m - currentMorph(iTime - 2.)) > 1e-5;
    bool needsUpdate = iFrame < 100 || (changing && iFrame % UPDATE_EVERY == 0);

    if (iFrame >= 1 && !needsUpdate) {
        O = texelFetch(iChannel0, ivec3(V), 0);
    }

    float field = targetField(V, m);
    if (field <= EPS) {
        O = vec4(field, 0., 0., 0.);
        return;
    }



    float best = 1e9;
    float bestLen = 0.;
    for (int k = 0; k < 27; k++) {
        if (k == 13)
            continue;
        vec3 offset = vec3(k % 3, (k / 3) % 3, k / 9) - 1.;
        ivec3 nb = clamp(ivec3(V) + ivec3(offset), ivec3(0), ivec3(127));
        float value = texelFetch(iChannel0, nb, 0).r;
        if (value < best) {
            best = value;
            bestLen = length(offset);
        }
    }
    O = vec4(best + bestLen * VOXEL, 0., 0., 0.);
}

const float WATER = -.62;
const float SIG = 9.0; 

const float SECONDS_PER_KEY = 5.;
const float DEPTH_SCALE = 10.;
const float SKY_DEPTH = 120.;
const float WATER_MAX_DEPTH = 80.;

const vec3 L = vec3(-.738, .422, .527);

float gMorph;

const int NK = 8;
const vec4 KEYS[NK] = vec4[NK](
    vec4(4.5, 1.20, .00, 2.4),
    vec4(3.0, .60, .00, 2.6),
    vec4(1.9, -.30, .10, 1.9),
    vec4(1.5, -.35, .20, 1.7),
    vec4(1.6, .50, .30, 2.0),
    vec4(1.5, 1.60, .00, 1.6),
    vec4(2.5, 1.00, .00, 2.4),
    vec4(3.8, .30, .00, 3.0));

vec4 key(int i) { return KEYS[((i % NK) + NK) % NK]; }

vec4 camPath(float u)
{
    int i = int(floor(u));
    float f = fract(u);
    vec4 p0 = key(i - 1), p1 = key(i), p2 = key(i + 1), p3 = key(i + 2);
    return .5 * (2. * p1 + (-p0 + p2) * f + (2. * p0 - 5. * p1 + 4. * p2 - p3) * f * f + (-p0 + 3. * p1 - 3. * p2 + p3) * f * f * f);
}

float morphAmount(float t)
{
    float p = fract(t / (float(NK) * SECONDS_PER_KEY));
    return smoothstep(.20, .40, p) - smoothstep(.75, .95, p);
}

float volS(vec3 p)
{
    return texture(iChannel0, .5 + .5 * p).r;
}

vec2 box(vec3 P, vec3 D)
{
    vec3 t0 = (-1. - P) / D, t1 = (1. - P) / D,
         m = min(t0, t1), M = max(t0, t1);
    return vec2(max(max(m.x, m.y), m.z), min(min(M.x, M.y), M.z));
}

vec3 sky(vec3 D)
{
    float y = max(D.y, 0.);
    vec3 c = mix(vec3(1., .62, .42), vec3(.08, .18, .42), pow(y, .45));
    float s = max(dot(D, L), 0.);
    c += vec3(1., .6, .3) * (pow(s, 8.) * .35 + pow(s, 400.) * 6.);
    return c;
}

vec3 albedo(vec3 p)
{
    vec3 sphereAlb = mix(vec3(.55, .08, .04), vec3(1., .55, .2), smoothstep(-.7, .5, p.y));

    float rad = length(p.xz);
    float tip = clamp(rad * .8 + (p.y + .5) * .45, 0., 1.);
    vec3 petalAlb = mix(vec3(1., .90, .86), vec3(.95, .28, .50), smoothstep(.15, .85, tip));
    float pod = smoothstep(.18, .12, rad) * smoothstep(-.34, -.28, p.y) * smoothstep(-.12, -.20, p.y);
    petalAlb = mix(petalAlb, vec3(.85, .70, .15), pod);

    return mix(sphereAlb, petalAlb, gMorph);
}

vec3 shade(vec3 p, vec3 N, vec3 D, float d)
{
    vec3 alb = albedo(p);
    float nl = dot(N, L);
    float dif = max(nl, 0.);
    float wrap = .5 + .5 * nl;
    wrap *= wrap;
    float ao = mix(.35, 1., clamp(volS(p + N * .06) / .06, 0., 1.));
    vec3 H = normalize(L - D);
    float spec = pow(max(dot(N, H), 0.), 60.);
    float fre = pow(1. - max(dot(N, -D), 0.), 3.);
    vec3 amb = mix(vec3(.04, .09, .10), vec3(.25, .30, .45), .5 + .5 * N.y);


    float tr = pow(max(dot(D, L), 0.), 3.) * exp(d * 15.0);
    vec3 trCol = mix(vec3(1., .6, .3), vec3(1., .65, .7), gMorph);

    vec3 c = alb * (vec3(1., .85, .7) * (dif * 1.2 + wrap * .3) + amb) * ao;
    c += spec * vec3(1., .8, .6) * 0.5 * ao;
    c += fre * sky(reflect(D, N)) * .35 * ao;
    c += alb * trCol * tr * 0.8; 
    return c;
}

vec4 volume(vec3 p, vec3 D, float l, float lmax, out float depth)
{
    const vec3 h = vec3(.03, 0, 0);
    vec3 col = vec3(0);
    float T = 1., r = 1., i = 0., dl = 1. / 128.;
    depth = 1e9;
    p += l * D;

    for (; l < lmax && r > .01 && i < 30.; i++, p += r * D, l += r)
        r = volS(p);

    for (; l < lmax && T > .01 && i < 1200.; i++, p += dl * D, l += dl) {
        float d = volS(p);
        float a = smoothstep(0., -1. / 128., d);
        if (a > 0.) {
            vec3 N = normalize(vec3(volS(p + h.xyy) - volS(p - h.xyy),
                volS(p + h.yxy) - volS(p - h.yxy),
                volS(p + h.yyx) - volS(p - h.yyx)));

            col += shade(p, N, D, d) * T * a * dl * 9.0;
            T *= exp(-9.0 * a * dl);

            if (depth > 1e8 && T < .5)
                depth = l;
        }
    }
    return vec4(col, T);
}

vec2 waterSlope(vec2 q, float t, float dist)
{
    vec2 swell = vec2(0);
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        vec2 dr = vec2(cos(fi * 2.4 + .3), sin(fi * 2.4 + .3));
        float f = 1.4 * pow(1.6, fi);
        swell += dr * cos(dot(q, dr) * f + t * (.5 + .2 * fi)) * .035 / (1. + .6 * fi);
    }

    vec2 ripple = vec2(0);
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        vec2 dr = vec2(cos(fi * 2.1 + 1.2), sin(fi * 2.1 + 1.2));
        float f = 9. * pow(1.5, fi);
        ripple += dr * cos(dot(q, dr) * f + t * (1.6 + .5 * fi)) * .018 / (1. + fi);
    }

    float rad = length(q);
    vec2 radial = q / max(rad, 1e-3);
    float env = smoothstep(.5, .9, rad) * exp(-max(rad - .8, 0.) * .9);
    float rings = (cos(rad * 16. - t * 2.2) * .06
                    + cos(rad * 27. - t * 3.1) * .025)
        * env;

    return swell / (1. + .05 * dist)
        + ripple / (1. + .25 * dist)
        + radial * rings / (1. + .15 * dist);
}

void mainImage(out vec4 fragColor, vec2 fragCoord)
{
    float t = iTime;
    vec2 uv = (2. * fragCoord - iResolution.xy) / iResolution.y;

    gMorph = morphAmount(t);

    vec4 k = camPath(t / SECONDS_PER_KEY);
    float theta = .22 * t + .35 * sin(.17 * t);
    float height = max(k.y, WATER + .2);

    vec3 P = vec3(k.x * sin(theta), height, k.x * cos(theta));
    vec3 T3 = vec3(0., k.z - .1, 0.);

    P += .02 * vec3(sin(t * 1.3), sin(t * 1.7 + 1.), sin(t * 1.1 + 2.));
    T3 += .015 * vec3(sin(t * 1.9 + 3.), sin(t * 1.5), sin(t * 1.2 + 1.));

    float roll = .03 * sin(.4 * t);
    vec3 up = vec3(sin(roll), cos(roll), 0.);

    vec3 ww = normalize(T3 - P),
         uu = normalize(cross(ww, up)),
         vv = cross(uu, ww),
         D = normalize(uv.x * uu + uv.y * vv + k.w * ww);

    if (fragCoord.x < 1. && fragCoord.y < 1.) {
        vec3 s = vec3(dot(L, uu), dot(L, vv), dot(L, ww));
        vec2 sUv = s.xy * k.w / max(s.z, 1e-3);
        vec2 sTex = .5 + .5 * sUv * vec2(iResolution.y / iResolution.x, 1.);
        float facing = smoothstep(0., .3, s.z) * .99;
        fragColor = vec4(sTex, facing, SKY_DEPTH);
        return;
    }

    vec2 B = box(P, D);
    float tw = D.y < -1e-3 ? (WATER - P.y) / D.y : 1e9;
    vec4 V = vec4(0, 0, 0, 1);
    float volDepth = 1e9;
    if (B.x < B.y && B.y > 0.)
        V = volume(P, D, max(B.x, 0.), min(B.y, tw), volDepth);

    vec3 bg;
    float depth = SKY_DEPTH;
    if (tw < 1e8) {
        vec3 ph = P + tw * D;
        depth = min(tw * DEPTH_SCALE, WATER_MAX_DEPTH);

        vec2 g = waterSlope(ph.xz, t, tw);
        vec3 Nw = normalize(vec3(-g.x, 1., -g.y));

        vec3 Rf = reflect(D, Nw);
        Rf.y = abs(Rf.y);
        vec2 B2 = box(ph, Rf);
        vec4 V2 = vec4(0, 0, 0, 1);
        float unusedDepth;
        if (B2.x < B2.y && B2.y > 0.)
            V2 = volume(ph, Rf, max(B2.x, 0.), B2.y, unusedDepth);
        vec3 refl = V2.rgb + V2.a * sky(Rf);

        float F = .10 + .90 * pow(1. - max(dot(Nw, -D), 0.), 4.);
        vec3 deep = vec3(.004, .022, .035) + vec3(0, .02, .02) * (.5 + .5 * Nw.x);
        vec3 wc = mix(deep, refl, F);
        bg = mix(sky(normalize(vec3(D.x, 0., D.z))), wc, exp(-.03 * tw));
    } else
        bg = sky(D);

    if (volDepth < 1e8)
        depth = volDepth * DEPTH_SCALE;

    fragColor = vec4(V.rgb + V.a * bg, depth);
}
